#[test]
fn amf_constants_match_the_header() {
    assert_eq!((AMF_OK, AMF_FAIL, AMF_NOT_SUPPORTED, AMF_EOF, AMF_REPEAT, AMF_INPUT_FULL), (0, 1, 10, 23, 24, 25), "AMF_RESULT");
    assert_eq!((AMF_MEMORY_HOST, AMF_MEMORY_DX11), (1, 3), "AMF_MEMORY_TYPE");
    assert_eq!((AMF_SURFACE_NV12, AMF_SURFACE_RGBA, AMF_SURFACE_P010), (1, 5, 10), "AMF_SURFACE_FORMAT");
    assert_eq!(AMF_DX11_1, 111, "AMF_DX_VERSION");
    assert_eq!(
        (AMF_VARIANT_BOOL, AMF_VARIANT_INT64, AMF_VARIANT_DOUBLE, AMF_VARIANT_RECT, AMF_VARIANT_SIZE, AMF_VARIANT_POINT, AMF_VARIANT_RATE, AMF_VARIANT_RATIO),
        (1, 2, 3, 4, 5, 6, 7, 8),
        "AMF_VARIANT_TYPE"
    );
    assert_eq!(AMF_VARIANT_INTERFACE, 12, "AMF_VARIANT_INTERFACE");
    assert_eq!((AMF_VIDEO_CONVERTER_COLOR_PROFILE_709, AMF_VIDEO_CONVERTER_COLOR_PROFILE_2020), (1, 2), "AMF_VIDEO_CONVERTER_COLOR_PROFILE_ENUM");
    assert_eq!((AMF_COLOR_PRIMARIES_BT709, AMF_COLOR_PRIMARIES_BT2020), (1, 9), "AMF_COLOR_PRIMARIES_ENUM");
    assert_eq!(
        (AMF_COLOR_TRANSFER_CHARACTERISTIC_BT709, AMF_COLOR_TRANSFER_CHARACTERISTIC_SMPTE2084, AMF_COLOR_TRANSFER_CHARACTERISTIC_ARIB_STD_B67),
        (1, 16, 18),
        "AMF_COLOR_TRANSFER_CHARACTERISTIC_ENUM"
    );
    assert_eq!(
        (
            AMF_VIDEO_ENCODER_OUTPUT_DATA_TYPE_IDR,
            AMF_VIDEO_ENCODER_OUTPUT_DATA_TYPE_I,
            AMF_VIDEO_ENCODER_OUTPUT_DATA_TYPE_P,
            AMF_VIDEO_ENCODER_OUTPUT_DATA_TYPE_B
        ),
        (0, 1, 2, 3)
    );
    assert_eq!((AMF_VIDEO_ENCODER_HEVC_OUTPUT_DATA_TYPE_IDR, AMF_VIDEO_ENCODER_HEVC_OUTPUT_DATA_TYPE_I, AMF_VIDEO_ENCODER_HEVC_OUTPUT_DATA_TYPE_P), (0, 1, 2));
    assert_eq!(
        (
            AMF_VIDEO_ENCODER_AV1_OUTPUT_FRAME_TYPE_KEY,
            AMF_VIDEO_ENCODER_AV1_OUTPUT_FRAME_TYPE_INTRA_ONLY,
            AMF_VIDEO_ENCODER_AV1_OUTPUT_FRAME_TYPE_INTER,
            AMF_VIDEO_ENCODER_AV1_OUTPUT_FRAME_TYPE_SWITCH,
            AMF_VIDEO_ENCODER_AV1_OUTPUT_FRAME_TYPE_SHOW_EXISTING
        ),
        (0, 1, 2, 3, 4)
    );
}
